-- ===================================================================
-- 04_functions_triggers.sql
--
-- Business-rule, resolver and audit functions, the tenant provisioning
-- functions, and every trigger. plpgsql bodies are late-bound so table
-- order does not matter here, but the tables must exist for CREATE TRIGGER.
--
-- Generated by the db_scripts consolidation. Fresh-install only:
-- there is no in-place upgrade path, no ALTER-after-the-fact section,
-- and no _migrations/ folder. Schema changes are made in the
-- CREATE statement itself and the database is rebuilt.
-- ===================================================================

BEGIN;

