-- ALTER ROLE tenant_dash_svc WITH PASSWORD :'TENANT_DASH_PWD';    -- → DATABASE_URL_TENANT
-- ALTER ROLE root_service     WITH PASSWORD :'ROOT_SVC_PWD';        -- → DATABASE_URL_SERVICE
-- ALTER ROLE campaign_svc    WITH PASSWORD :'CAMPAIGN_SVC_PWD';
-- ALTER ROLE user_mgmt_svc   WITH PASSWORD :'USER_MGMT_PWD';
-- ALTER ROLE notif_svc       WITH PASSWORD :'NOTIF_SVC_PWD';
-- ALTER ROLE intake_svc      WITH PASSWORD :'INTAKE_SVC_PWD';
-- ALTER ROLE analytics_svc   WITH PASSWORD :'ANALYTICS_SVC_PWD';

-- ===================================================================
-- v1.1: MULTI-ORG RLS FIX (auto-grant triggers + updated FK checks)
-- ===================================================================

-- ── AUTO-GRANT TRIGGER 1 ──────────────────────────────────────────
-- New org added to a tenant → all existing tenant_admins in that
-- tenant automatically receive a row for the new org.
CREATE OR REPLACE FUNCTION iam.auto_grant_tenant_admins_on_new_org()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  INSERT INTO iam.user_org_mapping (user_id, org_id, role_id, is_active, granted_by)
  SELECT uom.user_id, NEW.id, uom.role_id, TRUE, NULL
  FROM iam.user_org_mapping uom
  JOIN entity.organizations    o  ON o.id  = uom.org_id
  JOIN iam.user_roles       ur ON ur.id = uom.role_id
  WHERE o.tenant_id = NEW.tenant_id
    AND ur.name     = 'tenant_admin'
    AND uom.is_active
  ON CONFLICT (user_id, org_id) DO NOTHING;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS trg_auto_grant_tenant_admins_on_new_org ON entity.organizations;
CREATE TRIGGER trg_auto_grant_tenant_admins_on_new_org
  AFTER INSERT ON entity.organizations
  FOR EACH ROW EXECUTE FUNCTION iam.auto_grant_tenant_admins_on_new_org();

-- ── AUTO-GRANT TRIGGER 2 ──────────────────────────────────────────
-- User first granted tenant_admin in any org → they automatically
-- receive rows for all other existing orgs in the same tenant.
-- pg_trigger_depth() guard prevents recursive re-firing when this
-- function's own INSERTs trigger the same event.
CREATE OR REPLACE FUNCTION iam.auto_grant_all_orgs_on_tenant_admin()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_tenant_id UUID;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM iam.user_roles WHERE id = NEW.role_id AND name = 'tenant_admin'
  ) THEN RETURN NEW; END IF;

  SELECT tenant_id INTO v_tenant_id FROM entity.organizations WHERE id = NEW.org_id;

  INSERT INTO iam.user_org_mapping (user_id, org_id, role_id, is_active, granted_by)
  SELECT NEW.user_id, o.id, NEW.role_id, TRUE, NEW.granted_by
  FROM entity.organizations o
  WHERE o.tenant_id = v_tenant_id
    AND o.id       <> NEW.org_id
    AND NOT o.is_deleted
  ON CONFLICT (user_id, org_id) DO NOTHING;

  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS trg_auto_grant_all_orgs_on_tenant_admin ON iam.user_org_mapping;
CREATE TRIGGER trg_auto_grant_all_orgs_on_tenant_admin
  AFTER INSERT ON iam.user_org_mapping
  FOR EACH ROW EXECUTE FUNCTION iam.auto_grant_all_orgs_on_tenant_admin();

-- ── Cross-org action authority (Issue #3) ─────────────────────────────
-- Whether p_user_id may legitimately be recorded as the acting/assigned user
-- for a write in p_org_id. Returns TRUE when the user holds an active mapping to
-- the org (the normal path — the active org a shared user has switched into) OR
-- is a platform/tenant admin who acts across orgs WITHOUT a per-org mapping:
--   • super_admin  — platform scope, any org
--   • tenant_admin — any org within their own tenant
-- This is what lets the FK-org-scope triggers accept a super_admin/tenant_admin
-- write on a cross-org (e.g. unassigned) lead instead of raising — everyone else
-- still requires the mapping, so the check stays fail-closed. SECURITY DEFINER so
-- it can read iam/entity regardless of the caller's RLS context.
CREATE OR REPLACE FUNCTION iam.fn_actor_can_act_in_org(p_user_id UUID, p_org_id UUID)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE
  v_role TEXT;
BEGIN
  IF p_user_id IS NULL OR p_org_id IS NULL THEN
    RETURN FALSE;
  END IF;

  -- (1) Normal path: an active mapping to the org.
  PERFORM 1
  FROM iam.user_org_mapping uom
  JOIN iam.users u ON u.id = uom.user_id
  WHERE uom.user_id = p_user_id
    AND uom.org_id  = p_org_id
    AND uom.is_active
    AND u.is_active AND NOT u.is_deleted;
  IF FOUND THEN
    RETURN TRUE;
  END IF;

  -- (2) Platform/tenant admins act across orgs without a per-org mapping.
  --     Their GLOBAL role lives on iam.users.role_id (super_admin/tenant_admin
  --     are seeded that way; see 08_seed_tenants_orgs_users.sql).
  SELECT ur.name INTO v_role
  FROM iam.users u
  JOIN iam.user_roles ur ON ur.id = u.role_id
  WHERE u.id = p_user_id AND u.is_active AND NOT u.is_deleted;

  IF v_role = 'super_admin' THEN
    RETURN TRUE;                       -- platform scope: any org
  END IF;

  IF v_role = 'tenant_admin' THEN      -- tenant scope: any org in their tenant
    RETURN (
      SELECT o_target.tenant_id
      FROM entity.organizations o_target
      WHERE o_target.id = p_org_id AND NOT o_target.is_deleted
    ) = (
      SELECT o_home.tenant_id
      FROM iam.users u2
      JOIN entity.organizations o_home ON o_home.id = u2.org_id
      WHERE u2.id = p_user_id
    );
  END IF;

  RETURN FALSE;
END; $$;

-- Tier C: the single authoritative role resolver. Returns the acting user's role
-- NAME, RANK and DEPARTMENT for an org, straight from the unified iam ladder —
-- this is what every product service now calls instead of its own
-- <product>.member_roles lookup, so page guards and services can no longer
-- disagree. SECURITY DEFINER so it bypasses RLS on iam.user_roles /
-- iam.departments (same rationale as fn_user_org_rank above).
-- rank -1 / NULL role means "no active role in this org".
CREATE OR REPLACE FUNCTION iam.fn_user_org_role(p_user_id UUID, p_org_id UUID)
RETURNS TABLE (role TEXT, rank INT, department TEXT)
LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
  RETURN QUERY
  SELECT ur.name::TEXT, ur.rank, d.name::TEXT
  FROM iam.user_org_mapping uom
  JOIN iam.user_roles ur      ON ur.id = uom.role_id
  LEFT JOIN iam.departments d ON d.id = ur.department_id AND NOT d.is_deleted
  WHERE uom.user_id = p_user_id AND uom.org_id = p_org_id AND uom.is_active
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::TEXT, -1, NULL::TEXT;
  END IF;
END; $$;

-- Tier C3 — the effective capability matrix for one tenant, already resolved.
-- Walks the capability TREE and returns every node with a definite boolean, so a
-- caller never re-implements either rule:
--
--   precedence   tenant override > platform default > deny
--   inheritance  an ancestor that resolves FALSE prunes its whole subtree;
--                tool/page/tab additionally INHERIT the nearest ancestor grant,
--                while operation/scope always require their own explicit grant.
--
-- The asymmetry is deliberate. Nav can cascade because the operations beneath it
-- fail closed independently, so a newly added page can never grant new powers.
--
-- Effective SCOPE is not computed here: callers take the granted scope child with
-- the highest sort_order, which keeps this function a pure per-node answer.
--
-- SECURITY DEFINER for the same reason as fn_user_org_role: services read this on
-- a bare connection with no session GUCs and must not be subject to RLS while
-- doing so. The tenant is an explicit argument, taken from the verified auth context.
-- Signature changed in the tree rewrite (a `kind` column was added), and
-- CREATE OR REPLACE cannot change a function's return type — hence the DROP.
DROP FUNCTION IF EXISTS iam.fn_role_capability_matrix(UUID);
CREATE FUNCTION iam.fn_role_capability_matrix(p_tenant_id UUID)
RETURNS TABLE (role_name TEXT, capability_key TEXT, kind TEXT, parent_key TEXT, sort_order INT, granted BOOLEAN)
LANGUAGE sql STABLE SECURITY DEFINER AS $$
  WITH RECURSIVE grant_resolved AS (
    SELECT DISTINCT ON (rc.role_id, rc.capability_id)
           rc.role_id, rc.capability_id, rc.is_granted
    FROM iam.role_capabilities rc
    WHERE rc.tenant_id IS NULL OR rc.tenant_id = p_tenant_id
    ORDER BY rc.role_id, rc.capability_id, (rc.tenant_id IS NOT NULL) DESC
  ),
  walk AS (
    -- Roots are the tools. A tool is on only if explicitly granted.
    SELECT r.id AS role_id, r.name::TEXT AS role_name, c.key, c.kind, c.parent_key, c.sort_order,
           COALESCE(g.is_granted, FALSE) AS granted,
           COALESCE(g.is_granted, FALSE) AS nav_inherited
    FROM iam.user_roles r
    CROSS JOIN iam.capabilities c
    LEFT JOIN grant_resolved g ON g.role_id = r.id AND g.capability_id = c.id
    WHERE c.parent_key IS NULL AND c.is_active AND r.is_active
      AND (r.tenant_id IS NULL OR r.tenant_id = p_tenant_id)

    UNION ALL

    SELECT w.role_id, w.role_name, c.key, c.kind, c.parent_key, c.sort_order,
           CASE
             WHEN NOT w.granted THEN FALSE
             WHEN c.kind IN ('page','tab') THEN COALESCE(g.is_granted, w.nav_inherited)
             ELSE COALESCE(g.is_granted, FALSE)
           END,
           CASE WHEN c.kind IN ('page','tab')
                THEN COALESCE(g.is_granted, w.nav_inherited)
                ELSE w.nav_inherited END
    FROM walk w
    JOIN iam.capabilities c ON c.parent_key = w.key AND c.is_active
    LEFT JOIN grant_resolved g ON g.role_id = w.role_id AND g.capability_id = c.id
  )
  SELECT role_name, key::TEXT, kind::TEXT, parent_key::TEXT, sort_order, granted FROM walk;
$$;

-- Cleanup job: delete entries whose tokens have already expired
CREATE OR REPLACE FUNCTION iam.purge_expired_token_blocklist() RETURNS void
LANGUAGE sql SECURITY DEFINER AS $$
  DELETE FROM iam.token_blocklist WHERE expires_at < NOW();
$$;

